bool isPal(const std::string& s) {
    size_t l = 0, r = s.size() - 1;
    while (l < r) {
        if (s[l] != s[r]) return false;
        l++;
        r--;
    }
    return true;
}

void sortColors(std::vector<int>& a) {
    int lo = 0, mid = 0, hi = (int)a.size() - 1;
    while (mid <= hi) {
        if (a[mid] == 0) std::swap(a[lo++], a[mid++]);
        else if (a[mid] == 1) mid++;
        else std::swap(a[mid++], a[hi--]);
    }
}

